def parse(stdin):
    t = stdin.split()
    n = int(t[0])
    assert len(t) == n + 1
    return [int(x) for x in t[1:]]

def render(case):
    return str(len(case)) + chr(10) + " ".join(map(str, case))

def valid(case):
    return isinstance(case, list) and 1 <= len(case) <= 8 and all(type(x) is int and 0 <= x <= 5 for x in case)

def solve(stdin):
    c = parse(stdin)
    return str(len(set(c)))

def generate(seed, index, mode):
    if mode == "exhaustive":
        if index >= 63:
            return None
        n = (index % 3) + 1
        v = index // 3
        return [(v + i) % 6 for i in range(n)]
    import random
    rng = random.Random(seed + index)
    if mode == "random":
        n = rng.randint(1, 8)
        return [rng.randint(0, 5) for _ in range(n)]
    adv = [[0], [5], [0] * 8, [5] * 8, list(range(6)), [0, 5] * 4, [i % 2 for i in range(8)]]
    return adv[index % len(adv)][:]

def shrink(case):
    res = []
    if len(case) > 1:
        res.append(case[:-1])
        res.append(case[1:])
    for i, x in enumerate(case):
        if x > 0:
            c1, c2 = list(case), list(case)
            c1[i] = 0
            c2[i] = x // 2
            for c in (c1, c2):
                if c not in res and c != case:
                    res.append(c)
    return [c for c in res if valid(c)][:16]
